import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.Chlm-uVU.js";const u=JSON.parse('{"title":"Inspect retained DogStatsD contexts","description":"","frontmatter":{},"headers":[],"relativePath":"agent-data-plane/dogstatsd-top.md","filePath":"agent-data-plane/dogstatsd-top.md","lastUpdated":1786383338000}'),o={name:"agent-data-plane/dogstatsd-top.md"};function i(r,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="inspect-retained-dogstatsd-contexts" tabindex="-1">Inspect retained DogStatsD contexts <a class="header-anchor" href="#inspect-retained-dogstatsd-contexts" aria-label="Permalink to &quot;Inspect retained DogStatsD contexts&quot;">​</a></h1><p>Use <code>agent-data-plane dogstatsd top</code> to inspect which DogStatsD metric contexts Agent Data Plane (ADP) currently retains and to identify metric names with high cardinality.</p><h2 id="understand-what-top-reports" tabindex="-1">Understand what <code>top</code> reports <a class="header-anchor" href="#understand-what-top-reports" aria-label="Permalink to &quot;Understand what \`top\` reports&quot;">​</a></h2><p><code>top</code> snapshots the contexts currently retained by the <code>dsd_agg</code> aggregate transform. It does not measure packet or sample frequency, and it does not collect data over a time window. Use the separate <code>agent-data-plane dogstatsd stats</code> command when you need time-windowed sample counts and last-seen times.</p><p>A context&#39;s full identity consists of its metric name, host, client tags, and origin tags. The report groups these contexts by metric name, so contexts that differ only by host or origin tags still increase the context count for that name. The displayed tag cardinalities include only client tags; they do not include hosts or origin tags.</p><p>The report reflects Saluki&#39;s normal aggregate lifecycle. Contexts disappear after their aggregation state is flushed and no longer retained. Sparse counters can remain as idle counters while the aggregate transform emits zero values, then disappear according to the configured Saluki counter expiry. Do not interpret this behavior as an Agent-identical context time to live.</p><h2 id="request-and-analyze-a-dump" tabindex="-1">Request and analyze a dump <a class="header-anchor" href="#request-and-analyze-a-dump" aria-label="Permalink to &quot;Request and analyze a dump&quot;">​</a></h2><p>Run <code>top</code> without <code>--path</code> to request a new dump and analyze it:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane dogstatsd top</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Wrote /var/run/datadog/dogstatsd_contexts.json.zstd</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   Contexts	Metric name	(number of unique values for each tag)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">          3	request.count	(2 env, 1 service)</span></span></code></pre></div><p>Online requests use the same IPC-certificate-authenticated privileged API client as existing ADP commands. The API creates and returns only the server-local path <code>&lt;run_path&gt;/dogstatsd_contexts.json.zstd</code>.</p><p>The API does not return the artifact contents. The CLI reads the returned path directly, so the CLI process and ADP must see the same filesystem and path. If ADP runs in a container, run the CLI with the same mount or use the copy workflow in the next section. The API does not provide a remote download endpoint.</p><p>Use <code>--num-metrics</code> (<code>-m</code>) and <code>--num-tags</code> (<code>-t</code>) to change the default limits of 10 metric names and 5 tag keys:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane dogstatsd top --num-metrics 20 --num-tags 8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane dogstatsd top -m 20 -t 8</span></span></code></pre></div><p>Limits must be non-negative integers, and <code>top</code> rejects extra positional arguments.</p><p>The report orders metric names by descending context count and tag keys by descending unique-value count. It resolves ties lexically. When only one item exceeds a limit, the report displays that item; when two or more exceed it, the report replaces them with one remainder row or tag summary.</p><p>To create the artifact without rendering a report, run:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane dogstatsd dump-contexts</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Wrote /var/run/datadog/dogstatsd_contexts.json.zstd</span></span></code></pre></div><p><code>dump-contexts</code> takes no additional arguments. A successful request atomically replaces any prior file at the fixed path. The completed artifact remains there until an operator removes it.</p><h2 id="analyze-a-copied-dump-offline" tabindex="-1">Analyze a copied dump offline <a class="header-anchor" href="#analyze-a-copied-dump-offline" aria-label="Permalink to &quot;Analyze a copied dump offline&quot;">​</a></h2><p>Wait for <code>top</code> or <code>dump-contexts</code> to report success, then securely copy the completed artifact to the analysis host. Analyze the copy by passing its path explicitly:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane dogstatsd top --path /secure/cases/incident-123/dogstatsd_contexts.json.zstd</span></span></code></pre></div><p>You can combine <code>--path</code> (<code>-p</code>) with the metric and tag limits:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ agent-data-plane dogstatsd top -p /secure/cases/incident-123/dogstatsd_contexts.json.zstd -m 25 -t 10</span></span></code></pre></div><p>Offline mode reads only the supplied file and does not contact ADP. <code>top</code> requires the <code>--path</code> value and does not fall back to a file in the current working directory.</p><h2 id="interpret-context-and-tag-counts" tabindex="-1">Interpret context and tag counts <a class="header-anchor" href="#interpret-context-and-tag-counts" aria-label="Permalink to &quot;Interpret context and tag counts&quot;">​</a></h2><p>Each artifact record represents one full retained context. The <strong>Contexts</strong> column counts records with the same metric name, including contexts distinguished only by host or origin tags.</p><p>For the parenthesized tag summary, <code>top</code> deduplicates client tags across all records for the metric name. It treats the text before the first colon as the tag key and counts unique complete tag values. It treats a tag without a colon as its own key. For example, <code>(3 pod_name, 2 env)</code> means the retained contexts contain three distinct client tags whose key is <code>pod_name</code> and two whose key is <code>env</code>. It does not mean that ADP received three or two samples.</p><p>Use the remainder row to account for hidden contexts. For example, <code>17 (other 4 metrics)</code> means the four hidden metric names contain 17 retained contexts in total. A tag remainder such as <code>12 values in 3 other tags</code> reports the summed unique-value counts for the hidden tag keys.</p><h2 id="protect-and-remove-dump-artifacts" tabindex="-1">Protect and remove dump artifacts <a class="header-anchor" href="#protect-and-remove-dump-artifacts" aria-label="Permalink to &quot;Protect and remove dump artifacts&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>DogStatsD context dumps can contain metric names, hosts, client tags, and origin tags that reveal tenant or workload details. Treat every dump and copy as sensitive diagnostic data.</p></div><p>On Unix, ADP creates the artifact with mode <code>0600</code>, owned by the ADP process owner. On Windows, the artifact inherits the configured <code>run_path</code> directory ACL, matching the Datadog Agent; secure a custom <code>run_path</code> for the ADP service identity and intended administrators before requesting a dump. Keep the resulting access restriction when you copy or store the file, use an encrypted and access-controlled transfer method, and avoid placing it in shared temporary directories. Remove the server-side artifact and every copied artifact manually when you finish the investigation.</p><p>A later successful dump replaces the fixed server-side file but does not remove copies elsewhere. ADP does not apply a retention or cleanup policy to the completed file.</p><h2 id="understand-snapshot-consistency" tabindex="-1">Understand snapshot consistency <a class="header-anchor" href="#understand-snapshot-consistency" aria-label="Permalink to &quot;Understand snapshot consistency&quot;">​</a></h2><p>ADP currently has one <code>dsd_agg</code> owner. That owner constructs an internally consistent snapshot of its retained context map and then resumes processing. ADP serializes and compresses the snapshot after the owner resumes, so file creation does not hold the owner for the serialization work.</p><p>Snapshot construction uses memory proportional to the number of retained contexts, or O(contexts), in addition to the aggregate state itself. Serialization also retains that snapshot until publication finishes.</p><p>If ADP uses multiple aggregate owners in the future, each owner&#39;s snapshot remains internally consistent. The combined artifact would be a rolling snapshot because owners can respond at different moments; it would not represent one atomic instant across all owners.</p><h2 id="troubleshoot-errors" tabindex="-1">Troubleshoot errors <a class="header-anchor" href="#troubleshoot-errors" aria-label="Permalink to &quot;Troubleshoot errors&quot;">​</a></h2><p>Use the status or file error in the CLI output to choose a response:</p><ul><li><strong>Connection failure</strong>: Verify that the CLI can reach the configured privileged API endpoint.</li><li><strong>404 Not Found</strong>: The context-dump route is absent when DogStatsD is disabled. Also verify that the CLI targets the intended ADP privileged API endpoint.</li><li><strong>503 Service Unavailable</strong>: The aggregate snapshot owner is not running or stopped before it responded. Wait for the topology and <code>dsd_agg</code> to become healthy, then retry.</li><li><strong>504 Gateway Timeout</strong>: The aggregate owner did not return a snapshot within the 30-second API snapshot deadline. Check ADP health and load before retrying.</li><li><strong>500 Internal Server Error</strong>: ADP could not publish the artifact. Verify that <code>run_path</code> is configured, exists as a directory, and is writable by the ADP process. An empty <code>run_path</code> fails; ADP does not fall back to the current working directory.</li><li><strong>Missing or unreadable path</strong>: An online request returns a path on ADP&#39;s filesystem. If the request succeeds but <code>top</code> cannot open that path, give the CLI access to the same filesystem or use <code>dump-contexts</code>, copy the completed file, and run offline with <code>--path</code>.</li><li><strong>Malformed or truncated artifact</strong>: A zstd initialization error or a JSON record error usually indicates an incomplete, corrupt, or unsupported file. Copy the artifact again after dump publication completes and verify the transfer before retrying. Pass the exact file path because offline mode has no current-working-directory fallback.</li></ul><h2 id="artifact-interoperability" tabindex="-1">Artifact interoperability <a class="header-anchor" href="#artifact-interoperability" aria-label="Permalink to &quot;Artifact interoperability&quot;">​</a></h2><p>ADP writes a zstd-compressed stream of newline-delimited JSON (NDJSON) without a schema version. Every record uses the Agent diagnostic schema with these exact PascalCase fields:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;request.count&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Host&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node-a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Counter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;TaggerTags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pod_name:web-a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;MetricTags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;env:prod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;service:web&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;NoIndex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>TaggerTags</code> contains origin tags and <code>MetricTags</code> contains client tags. The Datadog Agent and ADP <code>dogstatsd top --path</code> command-line clients can each read artifacts produced by either implementation. Saluki detects zstd compression from the file&#39;s magic bytes rather than its filename, and it also accepts plain NDJSON with the same records.</p><p>This schema has no version field and serves as a diagnostic interoperability contract. It is not a supported metric ingestion API; do not send these records to a DogStatsD listener or depend on them as a general-purpose storage format.</p>`,44)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
